		    function NotScroll_LayerShow(elem) {
                $("html body").addClass('not_scroll');
                var typeHead = "#";
                if ($(typeHead + elem).size() > 0) {
                } else if ($("." + elem).size() > 0) {
                    typeHead = ".";
                }                
                $(typeHead + elem).show();
            }

            function NotScroll_LayerClose(elem) {
                $("html body").removeClass('not_scroll');
                var typeHead = "#";
                if ($(typeHead + elem).size() > 0) {
                } else if ($("." + elem).size() > 0) {
                    typeHead = ".";
                }
                $(typeHead + elem).hide();  
